	// Typefaces resolved by family-name matching only — font data was not
	// embedded (--no-font-data at decompile time). Text renders with the
	// host's version of the named family (or SKFontManager's substitute).
	private static readonly SKTypeface[] typefaceTable = BuildTypefaces();
	private static SKTypeface[] BuildTypefaces()
	{
		var tf = new SKTypeface[2];
		tf[0] = SKTypeface.Default; // index-0 slot; SkFont typeface index is 1-based
		tf[1] = SKTypeface.FromFamilyName("DejaVu Sans", 400, 5, SKFontStyleSlant.Upright);
		return tf;
	}

